fn sv(i: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    tab[i & 31]
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let r: i32 = if w < h { w / 2 - 40 } else { h / 2 - 40 };
    let pct: i32 = (t / 3) % 101;
    host::display::clear(0x08080c);
    let mut i: i32 = 0;
    while i < 24 {
        let idx: i32 = i * 32 / 24;
        let x: i32 = cx + sv(idx) * r / 127;
        let y: i32 = cy - sv(idx + 8) * r / 127;
        let col: i32 = if i < pct * 24 / 100 { 0x00e0ff } else { 0x1a1a22 };
        host::display::fill_rect(x - 7, y - 7, 15, 15, col);
        i = i + 1;
    }
    host::display::draw_number(cx - 28, cy - 12, pct, 0xffffff, 3);
    host::display::draw_string(cx + 24, cy - 12, "%", 0x808080, 3);
    host::display::present();
}
